#include <stdio.h>
int main(){
    int entries = 1024;
    int entry_bytes = 4;
    int first = entries * entry_bytes;
    int second_full = entries * entries * entry_bytes;
    int full = first + second_full;
    int second_half = (entries/2) * entries * entry_bytes;
    int half = first + second_half;
    printf("Entries per level: %d\n", entries);
    printf("Full table size (bytes): %d\n", full);
    printf("Half table size (bytes): %d\n", half);
    return 0;
}
